index=h.read_json(root/"campaign-index.json");plan=h.read_json(root/"private-plan.json")
done={s["scheduleOrdinal"] for s in index["sequences"]}
reason="Runtime camera attribution stopped at sourceWorldFrame 103983; first planned baseline failed exact-frame camera validation."
for s in plan["schedule"]:
 if s["scheduleOrdinal"] not in done:index["sequences"].append({"scheduleOrdinal":s["scheduleOrdinal"],"notRunReason":reason})
index.update(complete=False,scheduleComplete=False,terminalClassification="blocked_camera_attribution",failure=reason,captureCleanupVerified=True,configurationRestored=True,timeScaleRestored=20,feedbackId="AUTO-20260916-092605003-8E6F939A")
assess.atomic_json(root/"campaign-index.json",index)
manifests=[Path(json.loads(h.read_json(root/"scoutGet.json")["content"][0]["text"])["result"]["manifest"]["finalPath"]),Path(index["sequences"][0]["manifest"]["path"])]
summary={"sequences":[],"pairCount":0,"artifactCount":0,"cameraValidPairs":0,"candidateConditionsCaptured":[],"samplingLimitation":h.SAMPLING_LIMITATION}
for path in manifests:
 m=h.read_json(path);entry={"manifest":str(path),"sha256":h.digest(path),"counts":m["counts"],"pairs":[]}
 for child in m["children"]:
  a=child["actual"]["acquisition"];cam=a["cameraEvidence"]
  for image in child["artifacts"]:h.committed(image,path.parent)
  good=cam["available"] and cam["sourceWorldFrame"]==a["nrEvidence"]["left"]["sourceWorldFrame"]
  entry["pairs"].append({"ordinal":child["ordinal"],"frame":a["engineFrame"],"cameraFrame":cam["sourceWorldFrame"],"cameraAvailable":cam["available"],"cameraReason":cam["reason"],"matchedCamera":good,"timestampUs":a["monotonicTimestampUs"]})
  summary["pairCount"]+=1;summary["artifactCount"]+=len(child["artifacts"]);summary["cameraValidPairs"]+=good
 times=[v["timestampUs"] for v in entry["pairs"]];entry["actualIntervalsMs"]=[(b-a)/1000 for a,b in zip(times,times[1:])]
 summary["sequences"].append(entry)
summary.update(artifactIntegrity="all 48 native PNGs match committed size and SHA-256",plannedSequences=69,plannedCaptured=1,plannedUntested=68,qualityVerdict="indeterminate",reason=reason)
h.save_json(root/"capture-summary.json",summary)
try:
 result=h.analyse(root/"campaign-index.json",root/"analysis")
except h.EvidenceError as e:
 h.save_json(root/"analysis-result.json",{"ok":False,"reason":str(e),"expectedRejection":True})
 print(json.dumps({"captureSummary":{k:v for k,v in summary.items() if k!="sequences"},"analysisResult":str(e)}))

